"use client";

import * as React from "react";
import { cn } from "../../../lib/utils";

export interface ProgressRingProps extends React.HTMLAttributes<HTMLDivElement> {
  percentage: number;
  size?: number;
  strokeWidth?: number;
  color?: string;
  showLabel?: boolean;
}

function getProgressColor(clamped: number) {
  if (clamped >= 80) return "text-emerald-500";
  if (clamped >= 50) return "text-amber-500";
  return "text-rose-500";
}

function getProgressBgColor(clamped: number) {
  if (clamped >= 80) return "text-emerald-100 dark:text-emerald-950/60";
  if (clamped >= 50) return "text-amber-100 dark:text-amber-950/60";
  return "text-rose-100 dark:text-rose-950/60";
}

export function ProgressRing({
  percentage,
  size = 80,
  strokeWidth = 8,
  className,
  color: colorOverride,
  showLabel = false,
  ...props
}: ProgressRingProps) {
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const clamped = Math.min(100, Math.max(0, percentage));
  const strokeDashoffset = circumference - (clamped / 100) * circumference;

  const autoColor = getProgressColor(clamped);
  const color = colorOverride ?? autoColor;
  const bgColor = getProgressBgColor(clamped);

  const isCustomColor = Boolean(
    colorOverride && /^#|^rgb|^hsl|^var\(/i.test(colorOverride)
  );
  const strokeColor = isCustomColor ? colorOverride : "currentColor";
  const progressCircleClass = isCustomColor ? undefined : color;

  const roundedPercentage = Math.round(clamped);

  return (
    <div
      role="progressbar"
      aria-valuenow={roundedPercentage}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-label={props["aria-label"] || "Progress"}
      className={cn("relative inline-flex items-center justify-center", className)}
      {...props}
    >
      <svg width={size} height={size} className="transform -rotate-90">
        <title>{`Progress: ${roundedPercentage}%`}</title>
        <circle
          className={bgColor}
          strokeWidth={strokeWidth}
          stroke="currentColor"
          fill="transparent"
          r={radius}
          cx={size / 2}
          cy={size / 2}
        />
        <circle
          className={cn(progressCircleClass, "transition-all duration-1000 ease-in-out")}
          strokeWidth={strokeWidth}
          strokeDasharray={circumference}
          strokeDashoffset={strokeDashoffset}
          strokeLinecap="round"
          stroke={strokeColor}
          fill="transparent"
          r={radius}
          cx={size / 2}
          cy={size / 2}
        />
      </svg>
      {showLabel ? (
        <span className="absolute text-xs font-bold text-slate-800 dark:text-slate-200">
          {Math.round(clamped)}%
        </span>
      ) : null}
    </div>
  );
}
